import {
    Table,
    DomainPathColumn,
    StringColumn,
    TranslatedFieldColumn,
    BooleanColumn,
    ReferenceColumn,
    DecimalColumn,
    DomainIdColumn,
    UserRolesColumn,
    GenericColumn,
} from '../../db'

export const sys_app_application = Table({
    actions: ['read', 'update', 'delete', 'create'],
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_table_trace: true,
        ref_ac_columns: 'name',
        ref_ac_columns_search: true,
        ref_auto_completer: 'AJAXTableCompleter',
        update_synch: true,
    },
    audit: true,
    display: 'title',
    extends: 'sys_metadata',
    label: 'Application Menu',
    name: 'sys_app_application',
    schema: {
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        device_type: StringColumn({
            default: 'browser',
            choices: {
                any: {
                    label: 'Any',
                },
                browser: {
                    label: 'Browser',
                },
                mobile: {
                    label: 'Mobile',
                },
            },
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Modules without a specified device type are available on these devices',
                    label: 'Default device type',
                    plural: 'Default device types',
                },
            ],
        }),
        hint: TranslatedFieldColumn({
            attributes: {
                no_truncate: true,
            },
            label: [
                {
                    hint: 'Defines the text that appears in a tooltip when a user points to a link to this application',
                    label: 'Hint',
                    plural: 'Hints',
                },
            ],
            maxLength: 255,
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Application in use?',
                    label: 'Active',
                    plural: 'Active',
                },
            ],
        }),
        sys_overrides: ReferenceColumn({
            label: [
                {
                    hint: 'Application being overridden by the current record',
                    label: 'Overrides',
                    plural: 'Overrides',
                },
            ],
            referenceTable: 'sys_app_application',
        }),
        order: DecimalColumn({
            label: 'Order',
            maxLength: 15,
        }),
        title: TranslatedFieldColumn({
            label: [
                {
                    hint: 'Name appearing in Menu (translated)',
                    label: 'Title',
                    plural: 'Titles',
                },
            ],
            mandatory: true,
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the script belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
        roles: UserRolesColumn({
            array: true,
            attributes: {
                no_truncate: true,
            },
            label: [
                {
                    hint: 'Who can use this application',
                    label: 'Roles',
                    plural: 'Roles',
                },
            ],
            maxLength: 100,
        }),
        name: StringColumn({
            label: [
                {
                    hint: 'An internal name to uniquely identify applications that have the same title',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
        }),
        category: ReferenceColumn({
            label: [
                {
                    hint: 'Category permits application of styles',
                    label: 'Category',
                    plural: 'Categories',
                },
            ],
            referenceTable: 'sys_app_category',
            referenceFloats: true,
        }),
        view_name: StringColumn({
            label: 'View name',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        description: StringColumn({
            label: [
                {
                    hint: 'Provide a more detailed explanation of what this application does',
                    label: 'Description',
                    plural: 'Descriptions',
                },
            ],
            maxLength: 4000,
        }),
    },
    textIndex: true,
})
